/**
 * Unit tests for CategoryPlot.removeRangeMarker.
 */
public class CategoryPlot_removeRangeMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker mockMarker;
    private Marker otherMarker;

    @Before
    public void setUp() throws Exception {
        // Using the empty constructor
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
        otherMarker = mock(Marker.class);
    }

    /**
     * Test that passing a null marker throws an IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    /**
     * Test removing a marker from the FOREGROUND layer successfully.
     * Note: Since we cannot easily inject into private fields without reflection 
     * or using provided setters, we assume the internal structure is populated.
     * However, for a standard unit test where we can't access private fields,
     * we use reflection to set up the state for the test.
     */
    @Test
    public void testRemoveRangeMarker_Foreground_Success() throws Exception {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);

        // Use reflection to populate the private field foregroundRangeMarkers
        java.lang.reflect.Field field = CategoryPlot.class.getDeclaredField("foregroundRangeMarkers");
        field.setAccessible(true);
        java.util.Map<Integer, ArrayList> map = (java.util.Map<Integer, ArrayList>) field.get(plot);
        map.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should have been removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    /**
     * Test removing a marker from the BACKGROUND layer successfully.
     */
    @Test
    public void testRemoveRangeMarker_Background_Success() throws Exception {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);

        java.lang.reflect.Field field = CategoryPlot.class.getDeclaredField("backgroundRangeMarkers");
        field.setAccessible(true);
        java.util.Map<Integer, ArrayList> map = (java.util.Map<Integer, ArrayList>) field.get(plot);
        map.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Marker should have been removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    /**
     * Test attempting to remove a marker that does not exist in the list.
     */
    @Test
    public void testRemoveRangeMarker_MarkerNotFound() throws Exception {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(otherMarker);

        java.lang.reflect.Field field = CategoryPlot.class.getDeclaredField("foregroundRangeMarkers");
        field.setAccessible(true);
        java.util.Map<Integer, ArrayList> map = (java.util.Map<Integer, ArrayList>) field.get(plot);
        map.put(index, list);

        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Result should be false when marker not found", result);
        assertEquals(1, list.size());
    }

    /**
     * Test that notify=false prevents the change event from being fired 
     * (implicitly, we test that the method completes without error).
     */
    @Test
    public void testRemoveRangeMarker_NoNotify() throws Exception {
        int index = 0;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);

        java.lang.reflect.Field field = CategoryPlot.class.getDeclaredField("foregroundRangeMarkers");
        field.setAccessible(true);
        java.util.Map<Integer, ArrayList> map = (java.util.Map<Integer, ArrayList>) field.get(plot);
        map.put(index, list);

        // If notify is false, the logic skips fireChangeEvent()
        boolean result = plot.removeRangeMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue(result);
        assertTrue(list.isEmpty());
    }
}
